  KEY `idx_payments_payment_status` (`payment_status`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='金流付款紀錄；一筆訂單對應一次藍新付款流程';
